"""
Exhaustive small-scale verification of the sumset phenomenon.

For small n the statement "every delta-dense subset of [n] contains a sumset A + B with
|A| = |B| = k" can be checked by brute force over ALL subsets of the given size.  This
demo does exactly that and compares the truth with what the counting criterion certifies,
quantifying how conservative the criterion is.

It also brute-forces the affine-cube statement: for which (n, m) does every m-element
subset of [n] contain a proper two-dimensional cube u, u+a, u+b, u+a+b?

Everything is exact enumeration -- no sampling, no heuristics.
"""

from __future__ import annotations

import math
from itertools import combinations
from typing import Iterable, List, Optional, Sequence, Set, Tuple


def has_sumset(S: Set[int], k: int) -> bool:
    """Brute force: does S contain A + B with |A| = |B| = k?

    Uses the standard reduction: it suffices to search over A drawn from the differences
    S - S (translating A so that its minimum is 0 is harmless), and then to take B as the
    intersection of the translates S - a.
    """
    if k == 1:
        return len(S) >= 1
    diffs = sorted({s - t for s in S for t in S})
    for A in combinations(diffs, k):
        if A[0] != 0:
            continue
        B = set(S)
        for a in A:
            B = {b for b in B if a + b in S}
            if len(B) < k:
                break
        if len(B) >= k:
            return True
    return False


def worst_case_k(n: int, m: int, kmax: int = 4) -> int:
    """Largest k such that EVERY m-element subset of [n] contains a k x k grid (brute force)."""
    best = kmax
    for S in combinations(range(n), m):
        Ss = set(S)
        k = 0
        while k < best and has_sumset(Ss, k + 1):
            k += 1
        best = min(best, k)
        if best == 0:
            break
    return best


def counting_criterion(k: int, window: int, s_card: int) -> bool:
    if k <= 0:
        return True
    if k > s_card or k > window:
        return False
    return k * window**k <= s_card * (s_card - k) ** k


def certified_k(n: int, m: int) -> int:
    k = 0
    while counting_criterion(k + 1, 2 * n, m):
        k += 1
    return k


def has_proper_2cube(S: Set[int]) -> bool:
    """Does S contain u, u+a, u+b, u+a+b with a, b nonzero and the four points distinct?"""
    for u in S:
        cands = [x - u for x in S if x != u]
        for i, a in enumerate(cands):
            for b in cands[i + 1:]:
                if a != b and u + a + b in S:
                    return True
    return False


def worst_case_cube(n: int, m: int) -> bool:
    """True iff EVERY m-element subset of [n] contains a proper two-dimensional cube."""
    return all(has_proper_2cube(set(S)) for S in combinations(range(n), m))


def main() -> None:
    print("=" * 70)
    print("Exhaustive check: the largest grid forced in every m-subset of [n]")
    print("=" * 70)
    print(f"{'n':>4} {'m':>4} {'density':>8} {'true k':>7} {'certified k':>12}")
    for n, m in [(6, 4), (7, 5), (8, 5), (8, 6), (9, 6), (10, 7)]:
        true_k = worst_case_k(n, m)
        print(f"{n:>4} {m:>4} {m/n:>8.3f} {true_k:>7} {certified_k(n, m):>12}")
    print()
    print("The truth is well above the certified value: the counting criterion is a")
    print("worst-case guarantee, and the greedy maximum beats the average comfortably.")

    print()
    print("=" * 70)
    print("Exhaustive check: proper two-dimensional cubes")
    print("=" * 70)
    for n, m in [(6, 4), (7, 4), (7, 5), (8, 5), (8, 6)]:
        forced = worst_case_cube(n, m)
        print(f"  every {m}-subset of [{n}) contains a proper 2-cube: {forced}")
    print()
    print("Small cases already display the phenomenon that the asymptotic theorems")
    print("quantify: density alone forces parallelograms u, u+a, u+b, u+a+b.")


if __name__ == "__main__":
    main()

